WITH customer_stats AS (SELECT customer_id, SUM(CASE WHEN channel = 'partner' THEN shipping_fee ELSE 0 END) AS partner_shipping_fee FROM orders WHERE discount > 0.14 GROUP BY customer_id) SELECT c.id, c.credit_limit, c.country, cs.partner_shipping_fee FROM customers c LEFT JOIN customer_stats cs ON c.id = cs.customer_id WHERE cs.partner_shipping_fee >= 55 ORDER BY cs.partner_shipping_fee;
